/**
 * @method
 * @name scwin.tx_script_dts_dscs_noti_alram
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_script_dts_dscs_noti_alram = async function () {
    $c.util.getComponent("dma_scriptDtsDscsNotiAlramReq").set("SCREN_ID", "ULDSTF90500.gfm");
    $c.util.getComponent("dma_scriptDtsDscsNotiAlramReq").set("inputMessageId", "TBLD_DSCS_NOTI_ALRAM");
    // as-is 가 URL 에 싣던 값을 정적으로 못 읽었다 — 빈 파라미터로 보내지 않는다.
    throw { bizMessage: "보낼 입력값을 아직 읽지 못합니다(전환 미완) — SCREN_PROCES_TP_CD, DEPT_CD, USR_ID", unresolved: "query_param:SCREN_PROCES_TP_CD,DEPT_CD,USR_ID" };
    const sbmOptions = {
        id: "tx_script_dts_dscs_noti_alram",
        method: "post",
        action: "/notisvc.do",
        ref: "dma_scriptDtsDscsNotiAlramReq",
        target: "dtsDscsNotiAlram=body.content",
        isProcessMsg: false,
        submitErrorHandler: (typeof scwin['dts_dscs_noti_alram_onloaderror'] === 'function') ? scwin['dts_dscs_noti_alram_onloaderror'] : (typeof scwin['dts_dscs_noti_alram_onfail'] === 'function') ? scwin['dts_dscs_noti_alram_onfail'] : undefined
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions);
        { const dsh = (typeof scwin['dts_dscs_noti_alram_onloadcompleted'] === 'function') ? scwin['dts_dscs_noti_alram_onloadcompleted'] : ((typeof scwin['dts_dscs_noti_alram_onsuccess'] === 'function') ? scwin['dts_dscs_noti_alram_onsuccess'] : null); if (dsh) { const dsl = $c.util.getComponent('dtsDscsNotiAlram'); await dsh((dsl && dsl.getRowCount) ? dsl.getRowCount() : 0); } } }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf90500.tx_script_dts_dscs_noti_alram" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

