*/
scwin.search = async function () {
    /* sdd-asis-lifecycle:begin fn_search — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const url = "/notisvc.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + $c.fil.SCREN_PROCS_TP_CD_01 + "&method=getAlramList&inputMessageId=TBLD_DSCS_NOTI_ALRAM" + "&DEPT_CD=" + $c.session.getUserInfo("depCd") + "&USR_ID=" + $c.session.getUserInfo("id");

    await scwin.tx_script_dts_dscs_noti_alram();
    /* sdd-asis-lifecycle:end */
};


