*/
scwin.viewCheck = async function (noti_seq) {
    /* sdd-asis-lifecycle:begin fn_view_check — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const url = "/notisvc.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + $c.fil.SCREN_PROCS_TP_CD_03 + "&method=viewCheck&inputMessageId=TBLD_DSCS_NOTI_ALRAM" + "&NOTI_SVC_SEQ=" + noti_seq + "&DEPT_CD=" + $c.session.getUserInfo("depCd") + "&USR_ID=" + $c.session.getUserInfo("id");

