/**
 * @method
 * @name scwin.chkAlert
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.chkAlert = function () {
    /* sdd-asis-lifecycle:begin fn_chk_alert — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let read_yn = "";
    let dep_cd = "";
    let sound_yn = "";
    let isNotiYn = false;
    for (let i = scwin.dts_dscs_noti_alram.CountRow; i > 0; i--) {
        read_yn = scwin.dts_dscs_noti_alram.getCellData(i, "READ_YN");
        dep_cd = scwin.dts_dscs_noti_alram.getCellData(i, "DEP_CD");
        sound_yn = scwin.dts_dscs_noti_alram.getCellData(i, "SOUND_YN");
        if (read_yn === "N" && sound_yn === "Y" && dep_cd != null && scwin.gDepCd === dep_cd) {
            if (scwin.gDepCd === "4210") {
                isNotiYn = true;
                break;
            } else {
                if (scwin.gDepCd === "2430") {
                    scwin.playNotice();
                }
            }
        }
    }
    if (scwin.gDepCd === "4210") {
        if (isNotiYn) {
            scwin.playNotice();
        } else {
            scwin.stopNotice();
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.dsCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.dsCopy = function () {
    /* sdd-asis-lifecycle:begin fn_ds_copy — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.grd_ds.removeAll();
    (scwin.grd_ds && typeof scwin.grd_ds.setDataHeader === "function" && scwin.grd_ds.setDataHeader(scwin.dts_dscs_noti_alram.DataHeader));
    scwin.grd_ds.setJSON(scwin.dts_dscs_noti_alram.getRangeJSON(1, scwin.dts_dscs_noti_alram.CountRow, true));
    scwin.grd_ds.filter();
    if (scwin.chk_active.checked) {
        scwin.chkAlert();
        $c.frame.FrameShow("showna");
    }
    if (scwin.dts_dscs_noti_alram.CountRow > 0) {
        const no_count = scwin.grd_ds.getCellData(0, "NO_COUNT");
        if (no_count !== "0|0") {
